import * as React from "react";

import { GeoGeofence, type GeofenceZone, type TrackedDevice } from "@/components/lumesec/geo-geofence";

const initialZones: GeofenceZone[] = [
  { id: "depot", label: "Depot region", center: { lat: 52.52, lon: 13.405 }, radiusKm: 400 },
];

export function Example({ vehicles }: { vehicles: TrackedDevice[] }) {
  const [zones, setZones] = React.useState<readonly GeofenceZone[]>(initialZones);
  return (
    <GeoGeofence
      zones={zones}
      onZonesChange={setZones}
      devices={vehicles}
      onBreach={({ device, zone }) => console.log(`${device.label} left ${zone.label}`)}
    />
  );
}
